mapper.select:
SELECT *
FROM IMAGES
WHERE type = #{type} AND target_code = #{code}

mapper.update:
UPDATE IMAGES
SET order_seq = #{orderSeq}
WHERE type = #{type}
AND target_code = #{targetCode}
AND path = #{path}

mapper.delete:
DELETE FROM IMAGES
WHERE type = #{type}
AND target_code = #{targetCode}
AND path = #{path}
